    (public._demo_id(c, 't3'), 'trainee', 'Can we swap Thursday for a hotel gym session? They only have dumbbells up to 25 kg and a bike.', ((current_date + 0) + time '08:12') at time zone 'Asia/Riyadh', false, true),
